<script setup lang="ts">import{Head,useForm}from'@inertiajs/vue3';import AdvertiserPortalHeader from '@/components/Advertiser/AdvertiserPortalHeader.vue';import{Button}from'@/components/ui/button';import{Input}from'@/components/ui/input';const props=defineProps<{advertiser:any;membership:any}>();const canEdit=props.membership.role==='owner';const form=useForm({contact_name:props.advertiser.contact_name??'',contact_email:props.advertiser.contact_email??'',contact_phone:props.advertiser.contact_phone??'',billing_email:props.advertiser.billing_email??'',website_url:props.advertiser.website_url??'',billing_address:props.advertiser.billing_address??''});</script><template><Head title="Advertiser Account"/><div class="space-y-6 p-6"><AdvertiserPortalHeader title="Account" description="Organization contacts, billing details, and portal members." :advertiser="advertiser"/><form class="rounded-xl border p-5" @submit.prevent="form.put('/advertiser/account')"><fieldset :disabled="!canEdit" class="grid gap-4 md:grid-cols-2"><label class="text-sm">Contact name<Input v-model="form.contact_name" class="mt-2"/></label><label class="text-sm">Contact email<Input v-model="form.contact_email" type="email" class="mt-2"/></label><label class="text-sm">Contact phone<Input v-model="form.contact_phone" class="mt-2"/></label><label class="text-sm">Billing email<Input v-model="form.billing_email" type="email" class="mt-2"/></label><label class="text-sm md:col-span-2">Website URL<Input v-model="form.website_url" class="mt-2"/></label><label class="text-sm md:col-span-2">Billing address<textarea v-model="form.billing_address" rows="4" class="mt-2 w-full rounded-md border bg-background p-3"/></label></fieldset><div class="mt-5 flex justify-end"><Button v-if="canEdit" :disabled="form.processing">Save account</Button><p v-else class="text-sm text-muted-foreground">Only an advertiser owner can edit account details.</p></div></form><section class="rounded-xl border p-5"><h2 class="font-semibold">Portal members</h2><div class="mt-4 divide-y"><div v-for="m in advertiser.memberships" class="flex justify-between py-3"><div><p class="font-medium">{{m.user?.name}}</p><p class="text-sm text-muted-foreground">{{m.user?.email}}</p></div><span class="text-sm capitalize">{{m.role.replaceAll('_',' ')}}</span></div></div></section></div></template>
